//! Baked corpus store (API-V1 sections 6.13/6.14): the bake manifest,
//! corpus reads, source manifest + unpack. The bake data itself is
//! generated by tools/build_bake.py + the corpus bake step into the
//! repo's bake/ directory and embedded by build.rs; this module is
//! the runtime half.

use crate::hash::sha256_hex;
use crate::json::Json;
use crate::phext::{fmt_coord, parse_coord, Phext};
use crate::vol;
use std::fs;

/// Bake manifest bytes embedded at build time (build.rs generates
/// bake/manifest.json; the fallback is an honest empty manifest).
pub static MANIFEST_JSON: &str = include_str!("../bake/manifest.json");

/// Sealed corpus payloads, embedded at build time. Keys are the
/// artifact names of API-V1 section 6.13.
pub static SBOR_MD: &[u8] = include_bytes!("../bake/sbor.md");
pub static CYOA_SEALED: &[u8] = include_bytes!("../bake/cyoa.phext.xz");
pub static INCIPIT_SEALED: &[u8] = include_bytes!("../bake/incipit.phext.xz");
pub static SOURCE_SEALED: &[u8] = include_bytes!("../bake/source.phext.xz");

pub fn manifest() -> Json {
    crate::json::parse(MANIFEST_JSON).unwrap_or_else(|_| {
        Json::obj(vec![("artifacts", Json::Arr(vec![])), ("note", Json::s("bake manifest unparseable"))])
    })
}

pub fn manifest_artifact(name: &str) -> Option<Json> {
    let m = manifest();
    m.get("artifacts")?.as_arr()?.iter().find(|a| a.get("name").and_then(|v| v.as_str()) == Some(name)).cloned()
}

pub fn volumen_form() -> String {
    manifest()
        .get("volumen_form")
        .and_then(|v| v.as_str())
        .unwrap_or("redacted")
        .to_string()
}

/// Unseal a baked phext artifact into its scroll map (cached per call;
/// corpus reads are scroll-granular, section 6.13).
pub fn phext_of(sealed: &[u8]) -> Result<Phext, String> {
    let bytes = crate::xz::unseal(sealed)?;
    let text = String::from_utf8(bytes).map_err(|_| "corpus artifact is not UTF-8".to_string())?;
    Ok(Phext::parse(&text))
}

pub fn corpus_toc(name: &str) -> Result<Json, String> {
    let sealed = match name {
        "cyoa" => CYOA_SEALED,
        "incipit" => INCIPIT_SEALED,
        "source" => SOURCE_SEALED,
        _ => return Err(format!("no such corpus artifact: {}", name)),
    };
    let px = phext_of(sealed)?;
    let toc: Vec<Json> = px
        .toc()
        .iter()
        .map(|(c, n)| Json::obj(vec![("coord", Json::s(&fmt_coord(c))), ("bytes", Json::n(*n as f64))]))
        .collect();
    Ok(Json::obj(vec![
        ("artifact", Json::s(name)),
        ("scrolls", Json::n(toc.len() as f64)),
        ("toc", Json::Arr(toc)),
    ]))
}

pub fn corpus_scroll(name: &str, coord_s: &str) -> Result<Json, String> {
    let coord = parse_coord(coord_s).ok_or_else(|| format!("bad coordinate: {}", coord_s))?;
    match name {
        "sbor" => {
            let _ = coord;
            Err("the SBOR is a single text; read it whole via corpus sbor".into())
        }
        "volumen-index" => {
            let v = vol::baked_volumen_index();
            Ok(Json::obj(vec![
                ("artifact", Json::s(name)),
                ("coord", Json::s("3.1.8.0")),
                ("content", Json::s(&format!(
                    "Volumen index (redacted structural form): {} person lines (3.1.8.1..3.1.8.{}), {} volumes, cumulative boundaries {:?}. The full index text is a fleet/internal artifact; the structural derivation is what a public binary carries.",
                    v.coordinate_number, v.coordinate_number, v.volume_count, v.volume_boundaries
                ))),
            ]))
        }
        "cyoa" | "incipit" | "source" => {
            let sealed = match name {
                "cyoa" => CYOA_SEALED,
                "incipit" => INCIPIT_SEALED,
                _ => SOURCE_SEALED,
            };
            let px = phext_of(sealed)?;
            match px.get(&coord) {
                Some(text) => Ok(Json::obj(vec![
                    ("artifact", Json::s(name)),
                    ("coord", Json::s(coord_s)),
                    ("content", Json::s(text)),
                ])),
                None => Err(format!("no scroll at {} in {}", coord_s, name)),
            }
        }
        _ => Err(format!("no such corpus artifact: {}", name)),
    }
}

pub fn corpus_whole(name: &str) -> Result<Vec<u8>, String> {
    match name {
        "sbor" => Ok(SBOR_MD.to_vec()),
        "cyoa" => crate::xz::unseal(CYOA_SEALED),
        "incipit" => crate::xz::unseal(INCIPIT_SEALED),
        "source" => crate::xz::unseal(SOURCE_SEALED),
        "volumen-index" => Ok(vol::VOLUMEN_INDEX_MD.to_vec()),
        _ => Err(format!("no such corpus artifact: {}", name)),
    }
}

/// source.phext manifest: its Home scroll (1.1.1/1.1.1/1.1.1).
pub fn source_manifest() -> Result<Json, String> {
    let px = phext_of(SOURCE_SEALED)?;
    let home = px.get(&[1; 9]).cloned().unwrap_or_default();
    Ok(Json::obj(vec![
        ("manifest_scroll", Json::s(&home)),
        ("scrolls", Json::n(px.scrolls.len() as f64)),
    ]))
}

/// Unpack source.phext into a working tree (section 6.14 #70): every
/// scroll body carries a header — project / path / commit / sha256 —
/// and each file verifies against its header hash as it lands.
pub fn source_unpack(dir: &str) -> Result<Json, String> {
    let px = phext_of(SOURCE_SEALED)?;
    let mut written = 0u64;
    let mut files: Vec<Json> = Vec::new();
    for (coord, text) in &px.scrolls {
        if *coord == [1; 9] {
            continue; // the manifest itself
        }
        let mut lines = text.lines();
        let header = lines.next().unwrap_or("");
        // header form: project=<p> path=<f> commit=<c> sha256=<h>
        let mut project = "";
        let mut path = "";
        let mut hash = "";
        for kv in header.split_whitespace() {
            if let Some((k, v)) = kv.split_once('=') {
                match k {
                    "project" => project = v,
                    "path" => path = v,
                    "sha256" => hash = v,
                    _ => {}
                }
            }
        }
        if project.is_empty() || path.is_empty() {
            return Err(format!("source scroll at {} lacks a project/path header", fmt_coord(coord)));
        }
        let body = text[header.len()..].strip_prefix('\n').unwrap_or(&text[header.len()..]);
        if !hash.is_empty() && sha256_hex(body.as_bytes()) != hash {
            return Err(format!("unpack hash mismatch at {} ({}/{}) — aborting", fmt_coord(coord), project, path));
        }
        let dest = std::path::Path::new(dir).join(project).join(path);
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent).map_err(|e| e.to_string())?;
        }
        fs::write(&dest, body).map_err(|e| format!("write {}: {}", dest.display(), e))?;
        written += 1;
        files.push(Json::obj(vec![
            ("project", Json::s(project)),
            ("path", Json::s(path)),
            ("bytes", Json::n(body.len() as f64)),
        ]));
    }
    Ok(Json::obj(vec![
        ("unpacked_to", Json::s(dir)),
        ("files_written", Json::n(written as f64)),
        ("files", Json::Arr(files)),
    ]))
}

/// Verify the baked corpus against its manifest (hashes + sealed
/// readability). Divergence is reported, never silently replaced
/// (section 6.13 #67).
pub fn corpus_verify() -> Json {
    let m = manifest();
    let mut rows = Vec::new();
    let mut all_ok = true;
    if let Some(arts) = m.get("artifacts").and_then(|a| a.as_arr()) {
        for a in arts {
            let name = a.get("name").and_then(|v| v.as_str()).unwrap_or("?");
            let want = a.get("sha256").and_then(|v| v.as_str()).unwrap_or("");
            let got = match name {
                "sbor" => sha256_hex(SBOR_MD),
                "volumen-index" => sha256_hex(vol::VOLUMEN_INDEX_MD),
                _ => String::new(),
            };
            let sealed_check = match name {
                "cyoa" => crate::xz::unseal(CYOA_SEALED).map(|b| sha256_hex(&b)).unwrap_or_default(),
                "incipit" => crate::xz::unseal(INCIPIT_SEALED).map(|b| sha256_hex(&b)).unwrap_or_default(),
                "source" => crate::xz::unseal(SOURCE_SEALED).map(|b| sha256_hex(&b)).unwrap_or_default(),
                _ => got.clone(),
            };
            let ok = !want.is_empty() && (sealed_check == want || got == want);
            if !ok {
                all_ok = false;
            }
            rows.push(Json::obj(vec![
                ("artifact", Json::s(name)),
                ("manifest_sha256", Json::s(want)),
                ("baked_sha256", Json::s(&sealed_check)),
                ("match", Json::b(ok)),
            ]));
        }
    }
    Json::obj(vec![("all_match", Json::b(all_ok)), ("rows", Json::Arr(rows))])
}
